    base_target = 402.967426772491  # OPT_PARAM: {"initial": 402.967426772491, "min": 100.0, "max": 500.0, "type": "float"}
    lead_time_factor = 0.5  # OPT_PARAM: {"initial": 0.5, "min": 0.5, "max": 2.0, "type": "float"}
    demand_smoothing = 0.1  # OPT_PARAM: {"initial": 0.1, "min": 0.1, "max": 1.0, "type": "float"}

    adjusted_target = base_target * (1 + (quoted_lead_time - 6) * 0.1)  # Adjust for lead time
    smoothed_demand = demand_smoothing * last_demand + (1 - demand_smoothing) * 100.0  # Smooth demand
    target = max(adjusted_target, smoothed_demand * lead_time_factor)

    order_amount = max(0.0, target - on_hand_inventory - np.sum(pipeline_orders))
    return order_amount

